def baseNeg2(n: int) -> str:
    # If the number is zero, just return "0"
    if n == 0:
        return "0"

    res = []
    while n != 0:
        # For base -2, get remainder in {0,1}
        remainder = n % 2
        res.append(str(remainder))

        # Adjust n for next iteration
        n = (n - remainder) // -2

    # Join and reverse to get MSB at the front
    return ''.join(res[::-1])
